public int LastStoneWeight(int[] stones) {
    var desc = Comparer<int>.Create((a, b) => b.CompareTo(a));   // descending
    var heap = new PriorityQueue<int, int>(desc);                // max-heap
    foreach (int s in stones) heap.Enqueue(s, s);
    while (heap.Count > 1) {
        int y = heap.Dequeue(), x = heap.Dequeue();               // y ≥ x
        if (y != x) heap.Enqueue(y - x, y - x);
    }
    return heap.Count == 0 ? 0 : heap.Peek();
}

