public int FindKthLargest(int[] nums, int k) {
    int target = nums.Length - k;                 // index of the answer after sorting
    int lo = 0, hi = nums.Length - 1;
    var rng = new Random();
    while (true) {
        int pivot = nums[rng.Next(lo, hi + 1)];
        int lt = lo, i = lo, gt = hi;             // [lo, lt) < pivot, [lt, i) == pivot, (gt, hi] > pivot
        while (i <= gt) {
            if (nums[i] < pivot) Swap(nums, lt++, i++);
            else if (nums[i] > pivot) Swap(nums, i, gt--);
            else i++;
        }
        if (target < lt) hi = lt - 1;             // the answer is among the smaller ones
        else if (target > gt) lo = gt + 1;        // the answer is among the greater ones
        else return pivot;                        // landed in the block of equals
    }
}
static void Swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }

