public sealed class MinHeap<T> {
    T[] a = new T[16];
    int n;
    readonly IComparer<T> cmp;

    public MinHeap(IComparer<T> cmp = null) { this.cmp = cmp ?? Comparer<T>.Default; }
    public int Count => n;
    public T Peek() => n > 0 ? a[0] : throw new InvalidOperationException("heap is empty");

    public void Push(T x) {
        if (n == a.Length) Array.Resize(ref a, n * 2);
        int i = n++;
        while (i > 0) {                        // sift up: raise the "hole"
            int p = (i - 1) / 2;
            if (cmp.Compare(x, a[p]) >= 0) break;
            a[i] = a[p];                       // the parent is greater: move it down
            i = p;
        }
        a[i] = x;
    }

    public T Pop() {
        T top = Peek();
        T last = a[--n];
        a[n] = default;                        // do not hold a reference for the GC
        if (n > 0) SiftDown(last, 0);
        return top;
    }

    public T PushPop(T x) {                    // like EnqueueDequeue
        if (n == 0 || cmp.Compare(x, a[0]) <= 0) return x;
        T top = a[0];
        SiftDown(x, 0);
        return top;
    }

    void SiftDown(T x, int i) {                // sift down: lower the "hole"
        int half = n / 2;                      // nodes i < n / 2 have a left child
        while (i < half) {
            int c = 2 * i + 1;
            if (c + 1 < n && cmp.Compare(a[c + 1], a[c]) < 0) c++;   // the smaller child
            if (cmp.Compare(x, a[c]) <= 0) break;
            a[i] = a[c];
            i = c;
        }
        a[i] = x;
    }
}
